<script setup>
import { computed } from 'vue'
import { useActionsStore } from '@/stores/actions'
import { recordDraftOf, recordWorkflowState } from '@/utils/recordWorkflow'
const props = defineProps({ proposal: { type: Object, required: true }, compact: Boolean })
defineEmits(['open'])
const actions = useActionsStore()
const draft = computed(() => recordDraftOf(props.proposal))
const state = computed(() => recordWorkflowState(props.proposal, actions.submittingRecords[props.proposal.id], actions.recordErrors[props.proposal.id]))
const title = computed(() => draft.value.segments?.find(s => s.title?.trim())?.title || draft.value.rawContent?.slice(0, 48) || '这一次，值得留下')
</script>
<template>
  <button type="button" :class="['record-flight', `flight-${state.key}`, { compact }]" :data-workflow-id="proposal.id" :data-phase="state.key" @click="$emit('open')">
    <span class="flight-number" aria-hidden="true">{{ String(state.step + 1).padStart(2, '0') }}<i>✦</i></span>
    <span class="flight-content"><span class="flight-status" role="status"><i :class="{ moving: state.moving }" />{{ state.label }}<small v-if="state.key === 'review' || state.key === 'preparing'">尚未保存</small></span><strong :key="title">{{ title }}</strong><span class="flight-hint">{{ state.hint }}</span><span class="flight-track" aria-hidden="true"><i v-for="n in 4" :key="n" :class="{ passed: n <= state.step, current: n === state.step + 1 }" /></span></span>
    <span class="flight-open">{{ state.key === 'review' ? '打开，改成你的版本' : state.key === 'done' ? '查看记录' : state.key === 'failed' ? '查看并处理' : '查看进度' }}<b aria-hidden="true">↗</b></span>
  </button>
</template>
<style scoped>
.record-flight{--signal:#57ecf3;isolation:isolate;position:relative;display:flex;gap:22px;align-items:center;width:100%;min-width:0;overflow:hidden;text-align:left;color:#effaff;background:#0a2862;border:1px solid #6bbee375;border-left:5px solid var(--signal);padding:24px 26px;margin:0 0 18px;cursor:pointer;box-shadow:7px 7px 0 #061436;clip-path:polygon(0 0,calc(100% - 20px) 0,100% 20px,100% 100%,0 100%);transition:background .25s,translate .3s}.record-flight:before{content:'';position:absolute;inset:0;z-index:-1;background:repeating-linear-gradient(120deg,transparent 0 44px,#63c4ff08 45px 46px)}.flight-number{flex:0 0 68px;position:relative;color:var(--signal);font:italic 900 62px/.85 var(--font-display);letter-spacing:-.08em}.flight-number i{position:absolute;top:-12px;right:-1px;font-style:normal;font-size:25px;color:#ff5294}.flight-content{display:grid;gap:9px;min-width:0;flex:1}.flight-status{display:flex;gap:9px;align-items:center;font-size:12px;color:var(--signal);font-weight:800}.flight-status>i{height:7px;width:7px;background:currentColor;transform:rotate(45deg)}.flight-status small{font-size:10px;color:#aec1de;font-weight:400}.flight-content strong{font-size:20px;line-height:1.5;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;animation:flight-title .5s both}.flight-hint{color:#b6cce9;font-size:12px;line-height:1.7}.flight-track{display:flex;gap:5px;margin-top:5px;max-width:270px}.flight-track i{height:3px;flex:1;background:#77abcf32;transform:skewX(-30deg)}.flight-track .passed{background:var(--signal)}.flight-track .current{background:var(--signal);opacity:.6}.flight-open{display:flex;align-items:center;gap:18px;font-size:11px;flex-shrink:0}.flight-open b{font-size:30px;color:var(--signal);font-weight:400}.flight-review{--signal:#dfff4f;border-left-width:8px;background:#123678}.flight-review .flight-open{color:#092251;background:#dfff4f;padding:10px 13px;transform:rotate(-2deg);font-weight:800}.flight-review .flight-open b{color:inherit}.flight-failed{--signal:#ff6b9d}.flight-done{--signal:#a8efca}.flight-preparing:after,.flight-indexing:after{content:'';position:absolute;inset:0 auto 0 -40%;width:32%;background:linear-gradient(100deg,transparent,#70e8ff20,transparent);transform:skewX(-20deg);animation:flight-scan 2.4s ease-in-out infinite;pointer-events:none}.flight-indexing .flight-track .current,.flight-preparing .flight-track .current{animation:flight-pulse 1s alternate infinite}.moving{animation:flight-beat 1.4s ease-in-out infinite}.record-flight:hover{background:#164587;translate:0 -3px}.record-flight:focus-visible{outline:3px solid #ff5294;outline-offset:4px}.compact{padding:17px 18px;gap:15px;margin:13px 0;max-width:620px}.compact .flight-number{font-size:42px;flex-basis:43px}.compact .flight-content strong{font-size:15px}.compact .flight-open{font-size:0;gap:0;background:none;padding:0}.compact .flight-open b{font-size:26px;color:var(--signal)}
@keyframes flight-scan{0%{left:-40%}85%,100%{left:130%}}@keyframes flight-pulse{to{opacity:.2}}@keyframes flight-beat{50%{transform:rotate(135deg) scale(1.5)}}@keyframes flight-title{from{opacity:.2;transform:translateY(9px)}to{opacity:1;transform:none}}
@media(max-width:650px){.record-flight{gap:14px;padding:20px 16px;flex-wrap:wrap}.flight-number{font-size:48px;flex-basis:46px}.flight-content strong{font-size:17px}.flight-open{margin-left:60px;font-size:11px}.flight-hint{font-size:11px}.compact .flight-open{margin-left:0}.compact{flex-wrap:nowrap}.compact .flight-hint{display:none}}
@media(prefers-reduced-motion:reduce){.record-flight,.record-flight *,.record-flight:after{animation:none!important;transition:none!important}}
@media(max-width:650px){.flight-content{flex-basis:calc(100% - 60px)}.flight-open{flex-basis:calc(100% - 60px)}.compact .flight-content{flex-basis:0}.compact .flight-open{flex-basis:auto}}
</style>
